# Repeat / motif finding: longest repeated exact substring, and over-represented k-mers
from collections import Counter

def top_kmers(s, k, n=10):
    c = Counter(s[i:i+k] for i in range(len(s)-k+1))
    return c.most_common(n)

for k in (6,8,10,12,15,18,20,24,30):
