comp = {"A":"T","T":"A","C":"G","G":"C"}
def rc(s): return "".join(comp[c] for c in reversed(s))

def orfs(s, min_aa=60):
    res=[]
    for frame in range(3):
        i=frame
        while i < len(s)-2:
            if s[i:i+3]=="ATG":
                j=i
                while j < len(s)-2:
                    cod=s[j:j+3]
                    if cod in ("TAA","TAG","TGA"):
                        break
                    j+=3
                if j-i >= min_aa*3:
                    res.append((i+1, j+2, (j-i)//3, frame+1, s[i:j+3]))
                i=j+3
            else:
                i+=3
    return res

