def longest_orf(s, min_aa=30):
    out=[]
    for f in range(3):
        i=f
        while i<len(s)-2:
            if s[i:i+3]=="ATG":
                j=i
                while j<len(s)-2 and s[j:j+3] not in ("TAA","TAG","TGA"):
                    j+=3
                aa=(j-i)//3
                if aa>=min_aa:
                    out.append((i+1,j+2,aa,f+1))
                i=j+3
            else: i+=3
    return out

